export default function main({ inventory, shardBytes }) {
  const byDir = new Map();
  for (const u of inventory) { const d = u.path.split('/').slice(0, -1).join('/'); if (!byDir.has(d)) byDir.set(d, []); byDir.get(d).push(u); }
  const shards = []; let cur = { id: 's0', units: [], bytes: 0 };
  for (const [, units] of [...byDir.entries()].sort()) for (const u of units) {
    if (cur.units.length && cur.bytes + u.bytes > shardBytes) { shards.push(cur); cur = { id: 's' + shards.length, units: [], bytes: 0 }; }
    cur.units.push(u.id); cur.bytes += u.bytes;
  }
  if (cur.units.length) shards.push(cur);
  return { shards, unitIds: inventory.map(u => u.id), unitCount: inventory.length };
}

export default function main({ subject: { units, out } }) {
  const want = new Set(units), got = new Set(out.read);
  const missing = units.filter(u => !got.has(u));
  const stray = out.findings.filter(f => !want.has(f.unit));
  return { pass: missing.length === 0 && stray.length === 0, missing, stray: stray.length };
}

export default function main({ shards, results }) {
  const findings = new Map(); const failedShards = [];
  results.forEach((r, i) => {
    if (!r || r.$error) { failedShards.push(shards[i].id); return; }
    for (const f of r.read.findings) findings.set(f.unit + '|' + f.location + '|' + f.reason, f);
  });
  return { failedShards, findings: [...findings.values()] };
}

export default function main({ shards, n }) {
  const k = Math.max(1, Math.floor(shards.length / n));
  return { sample: shards.filter((_, i) => i % k === 0).slice(0, n) };
}

export default function main({ subject: { second, first, maxMissRate } }) {
  const key = f => f.unit + '|' + f.location;
  const have = new Set(first.map(key)); let extra = 0, units = 0;
  for (const r of second) { if (!r || r.$error) continue; units += r.reread.read.length; extra += r.reread.findings.filter(f => !have.has(key(f))).length; }
  const rate = units ? extra / units : 1;
  return { pass: rate <= maxMissRate, missRatePerUnit: rate, unitsSampled: units };
}
